-- =============================================================================
-- NoteHive V1: full schema.
--
-- Conventions:
--   * tenant column is org_id (the organization IS the tenant); UUID PKs are
--     generated by the application (UUIDv4).
--   * Row-Level Security: tenant-owned tables are restricted to the
--     notehive_app role by the session GUC app.tenant_id, set per transaction
--     (SET LOCAL) by TenantBoundInterceptor. Fail-closed: NULL GUC => 0 rows.
--     Auth-layer tables (organizations, users, sessions) are intentionally
--     NOT RLS-bound because login runs before a tenant is known; they are
--     protected by application logic + unique constraints.
--   * WAL durability is a server setting (see deploy/docker/initdb and the
--     compose command); transactions here rely on synchronous_commit=on.
-- =============================================================================

-- ----------------------------------------------------------------- roles
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'notehive_app') THEN
        CREATE ROLE notehive_app NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'notehive_worker') THEN
        -- BYPASSRLS: cross-tenant maintenance only (bloom rebuild, retention)
        CREATE ROLE notehive_worker NOLOGIN BYPASSRLS;
    END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO notehive_app, notehive_worker;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO notehive_app, notehive_worker;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO notehive_app, notehive_worker;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO notehive_app, notehive_worker;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
    GRANT USAGE, SELECT ON SEQUENCES TO notehive_app, notehive_worker;

-- ----------------------------------------------------------------- auth layer
CREATE TABLE organizations (
    id           uuid PRIMARY KEY,
    name         varchar(120) NOT NULL,
    slug         varchar(60)  NOT NULL UNIQUE,
    owner_email  varchar(254),
    created_at   timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    org_id        uuid NOT NULL REFERENCES organizations(id),
    username      varchar(40) NOT NULL,
    email         varchar(254) NOT NULL,
    display_name  varchar(80) NOT NULL,
    password_hash text NOT NULL,              -- PBKDF2-WithHmacSHA256, per-user salt
    status        varchar(16) NOT NULL DEFAULT 'active',
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
-- hash-mapping: uniqueness enforced on normalized (lower) values; the Bloom
-- filter in front of these is a pre-check only, never authoritative.
CREATE UNIQUE INDEX users_username_lkey ON users (lower(username));
CREATE UNIQUE INDEX users_email_lkey    ON users (lower(email));
CREATE INDEX users_org_idx ON users (org_id);

CREATE TABLE sessions (
    id                 uuid PRIMARY KEY,
    user_id            uuid NOT NULL REFERENCES users(id),
    org_id             uuid NOT NULL,
    family_id          uuid NOT NULL,          -- refresh reuse => revoke whole family
    refresh_hash       char(64) NOT NULL UNIQUE, -- sha256(refresh token), never the token
    idle_expires_at    timestamptz NOT NULL,
    absolute_expires_at timestamptz NOT NULL, -- 24h / 72h remember-me, server-enforced
    revoked_at         timestamptz,
    revoked_reason     varchar(40),
    user_agent         varchar(200),
    ip                 varchar(64),
    created_at         timestamptz NOT NULL DEFAULT now(),
    last_used_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_idx ON sessions (user_id, family_id);
CREATE INDEX sessions_expiry_idx ON sessions (idle_expires_at) WHERE revoked_at IS NULL;

-- ----------------------------------------------------------------- teams
CREATE TABLE teams (
    id         uuid PRIMARY KEY,
    org_id     uuid NOT NULL REFERENCES organizations(id),
    name       varchar(80) NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    archived_at timestamptz
);
CREATE UNIQUE INDEX teams_org_name_lkey ON teams (org_id, lower(name)) WHERE archived_at IS NULL;
CREATE INDEX teams_org_idx ON teams (org_id) WHERE archived_at IS NULL;

CREATE TABLE team_members (
    id        uuid PRIMARY KEY,
    org_id    uuid NOT NULL,
    team_id   uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
    user_id   uuid NOT NULL REFERENCES users(id),
    role      varchar(16) NOT NULL,            -- owner | editor | viewer
    added_by  uuid,
    joined_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX team_members_uniq ON team_members (team_id, user_id);
CREATE INDEX team_members_user_idx ON team_members (user_id, org_id);
CREATE INDEX team_members_team_idx ON team_members (team_id);

-- ----------------------------------------------------------------- notes
CREATE TABLE notes (
    id          uuid PRIMARY KEY,
    org_id      uuid NOT NULL,
    team_id     uuid NOT NULL REFERENCES teams(id),
    title       varchar(200) NOT NULL,
    body        text NOT NULL DEFAULT '',
    format      varchar(10) NOT NULL DEFAULT 'markdown',
    version     integer NOT NULL DEFAULT 1,    -- optimistic locking
    created_by  uuid NOT NULL,
    updated_by  uuid NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    deleted_at  timestamptz,
    -- full-text search (safe by construction: generated column, no trigger)
    search tsvector GENERATED ALWAYS AS
        (to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(body, ''))) STORED
);
-- keyset pagination index (seek by updated_at,id) + team listing
CREATE INDEX notes_keyset_idx ON notes (org_id, team_id, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX notes_author_idx ON notes (org_id, created_by) WHERE deleted_at IS NULL;
CREATE INDEX notes_search_gin ON notes USING gin (search) WHERE deleted_at IS NULL;

CREATE TABLE note_versions (
    id            uuid PRIMARY KEY,
    org_id        uuid NOT NULL,
    note_id       uuid NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    version       integer NOT NULL,
    title         varchar(200) NOT NULL,
    -- data compression: large snapshots stored gzip-deflated; small ones raw
    body_bytes    bytea NOT NULL,
    compressed    boolean NOT NULL DEFAULT false,
    original_size integer NOT NULL,
    checksum      char(64) NOT NULL,           -- sha256 of the raw body (integrity)
    author_id     uuid NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    UNIQUE (note_id, version)
);
CREATE INDEX note_versions_keyset_idx ON note_versions (note_id, version DESC);

CREATE TABLE comments (
    id         uuid PRIMARY KEY,
    org_id     uuid NOT NULL,
    note_id    uuid NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    author_id  uuid NOT NULL REFERENCES users(id),
    body       varchar(8000) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz
);
CREATE INDEX comments_note_idx ON comments (note_id, created_at) WHERE deleted_at IS NULL;

-- ----------------------------------------------------------------- infra
CREATE TABLE outbox_events (
    id              bigserial PRIMARY KEY,
    event_id        uuid NOT NULL UNIQUE,
    event_type      varchar(60) NOT NULL,
    schema_version  integer NOT NULL DEFAULT 1,
    org_id          uuid NOT NULL,
    aggregate_id    uuid NOT NULL,
    occurred_at     timestamptz NOT NULL,
    correlation_id  uuid,
    payload         jsonb NOT NULL,
    status          varchar(10) NOT NULL DEFAULT 'pending',  -- pending|published|failed|dead
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    created_at      timestamptz NOT NULL DEFAULT now()
);
-- relay ordering + claim efficiency
CREATE INDEX outbox_due_idx ON outbox_events (status, next_attempt_at) WHERE status IN ('pending','failed');

CREATE TABLE processed_events (
    event_id     uuid NOT NULL,
    group_name   varchar(60) NOT NULL,
    org_id       uuid,
    processed_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (event_id, group_name)
);

CREATE TABLE idempotency_records (
    org_id          uuid NOT NULL,
    idempotency_key varchar(120) NOT NULL,
    user_id         uuid NOT NULL,
    method          varchar(8) NOT NULL,
    path            varchar(300) NOT NULL,
    request_hash    char(64) NOT NULL,
    status          varchar(10) NOT NULL DEFAULT 'pending',  -- pending|completed
    response_code   integer,
    response_body   text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    completed_at    timestamptz,
    PRIMARY KEY (org_id, idempotency_key)
);
CREATE INDEX idempotency_created_idx ON idempotency_records (created_at);

CREATE TABLE audit_logs (
    id          bigserial PRIMARY KEY,
    org_id      uuid NOT NULL,
    actor_id    uuid,
    action      varchar(60) NOT NULL,
    target_type varchar(40),
    target_id   uuid,
    detail      jsonb NOT NULL DEFAULT '{}',
    occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_recent_idx ON audit_logs (org_id, occurred_at DESC);

CREATE TABLE webhook_endpoints (
    id          uuid PRIMARY KEY,
    org_id      uuid NOT NULL,
    url         varchar(500) NOT NULL,
    secret_enc  bytea NOT NULL,                -- AES-GCM at rest
    event_types text[] NOT NULL DEFAULT '{}',  -- empty = all events
    active      boolean NOT NULL DEFAULT true,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_endpoints_org_idx ON webhook_endpoints (org_id) WHERE active;

-- ----------------------------------------------------------------- triggers
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER users_touch BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER notes_touch BEFORE UPDATE ON notes
    FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

-- ----------------------------------------------------------------- RLS
DO $$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT t FROM unnest(ARRAY[
        'teams', 'team_members', 'notes', 'note_versions', 'comments',
        'idempotency_records', 'audit_logs', 'webhook_endpoints'
    ]) AS t LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', r.t);
        EXECUTE format($f$
            CREATE POLICY %1$I_tenant_isolation ON %1$I TO notehive_app
            USING (org_id = current_setting('app.tenant_id', true)::uuid)
            WITH CHECK (org_id = current_setting('app.tenant_id', true)::uuid)
        $f$, r.t);
    END LOOP;
END
$$;

-- audit trail is append-only for the application role
CREATE POLICY audit_logs_no_update ON audit_logs TO notehive_app
    FOR UPDATE USING (false);
CREATE POLICY audit_logs_no_delete ON audit_logs TO notehive_app
    FOR DELETE USING (false);
